mapper.select:
SELECT 
  FROM BSYMENU MENU
 WHERE MENU.DEL_YN = 'N'

   AND (UPPER(MENU.MENU_KEY) LIKE CONCAT('%', UPPER(#{KEYWORD}), '%')
        OR UPPER(MENU.MENU_NAME) LIKE CONCAT('%', UPPER(#{KEYWORD}), '%'))


   AND MENU.PARENT_MENU_KEY = #{PARENT_MENU_KEY}


   AND MENU.MENU_TYPE_CODE = #{MENU_TYPE_CODE}


   AND MENU.PROGRAM_KEY = #{PROGRAM_KEY}


   AND MENU.USE_YN = #{USE_YN}

 ORDER BY MENU.PARENT_MENU_KEY NULLS FIRST, MENU.SORT_ORDER, MENU.MENU_KEY

mapper.update:
UPDATE BSYMENU MENU
   SET DEL_YN = 'Y', USE_YN = 'N', MOD_DT = CURRENT_TIMESTAMP, MOD_BY = #{MOD_BY}
 WHERE MENU.MENU_KEY = #{MENU_KEY}
   AND MENU.DEL_YN = 'N'
